#include <iostream>
using namespace std;
typedef struct { int Tu; int Mau; } PS;
PS operator += (PS &p1, PS p2) {
    p1.Tu = p1.Tu*p2.Mau + p2.Tu*p1.Mau;
    p1.Mau = p1.Mau * p2.Mau;
    return p1;
}
template <typename T>
PS operator += (PS &p1, T p2) {
    p1.Tu += p2 * p1.Mau;
    return p1;
}
int main(){
    PS p1 = {3,4}, p2 = {2,3};
    float x = 2.6;
    p1 += p2;
    p2 += x;
    cout << "p1=" << p1.Tu << "/" << p1.Mau << " Va p2=" << p2.Tu << "/" << p2.Mau;
}

