/*
 * remove : Loại bỏ 1 phần tử khỏi danh sách
 * a_list là biến tổng thể.
 * T_node là kiểu phần tử thuộc danh sách
 */

void remove ( T_node *p)
{
        T_node **i = &a_list ;
        for ( ; (*i) != NULL && (( *i) != p) ; *i = ((*i) -> next) ) ;
        if ( *i != NULL)
                ( *i) = (*i) -> next;
        if ( p != NULL)
                nodepree (p); //giải phóng node trỏ bởi p
}

